        return [row[::-1] for row in g[::-1]]
    def flip_v(g):
        return g[::-1]
    def flip_h(g):
        return [row[::-1] for row in g]

    out = []
    for i in range(9):
        out.append([])
        for j in range(9):
            bi, bj = i // 3, j // 3
            si, sj = i % 3, j % 3

            if bi % 2 == 1 and bj % 2 == 1:
                val = grid[si][sj]  # original
            elif bi % 2 == 0 and bj % 2 == 0:
                val = rot180(grid)[si][sj]  # corners
            elif bi % 2 == 0 and bj % 2 == 1:
                val = flip_v(grid)[si][sj]  # top edge
            elif bi == 1 and bj % 2 == 0:
                val = flip_h(grid)[si][sj]  # mid edge
            else:
                val = grid[0][0]
            out[i].append(val)
    return out

test_input = [[8,8,6],[6,3,6],[6,8,8]]
test_output_flip = make_output_flip(test_input)

print("Test output (flip-based):")
for row in test_output_flip:
    print(row)

